mapper.select:
select watchlist_id, user_id, ts_code, name, industry, create_time
from stock_watchlist
where user_id = #{userId} and ts_code = #{tsCode}

select w.ts_code,
       coalesce(r.name, w.name) as name,
       coalesce(r.industry, w.industry) as industry,
       r.pe_ttm, r.pb, r.roe, r.dv_ttm, r.total_mv_yi,
       r.close_price, r.ma120, r.price_ma120_ratio, r.ma120_signal,
       r.result_id, r.run_id, r.strategy_code, r.trade_date,
       case when r.result_id is null then 1 else 0 end as out_of_pool
from stock_watchlist w
left join stock_screen_result r
  on r.run_id = #{runId} and r.ts_code = w.ts_code
where w.user_id = #{userId}

    and w.ts_code like concat('%', #{query.tsCode}, '%')


    and coalesce(r.name, w.name) like concat('%', #{query.name}, '%')


    and coalesce(r.industry, w.industry) like concat('%', #{query.industry}, '%')

 and r.pe_ttm >= #{query.peTtmMin}
 and r.pe_ttm <= #{query.peTtmMax}
 and r.pb >= #{query.pbMin}
 and r.pb <= #{query.pbMax}
 and r.roe >= #{query.roeMin}
 and r.roe <= #{query.roeMax}
 and r.dv_ttm >= #{query.dvTtmMin}
 and r.dv_ttm <= #{query.dvTtmMax}
 and r.total_mv_yi >= #{query.totalMvYiMin}
 and r.total_mv_yi <= #{query.totalMvYiMax}
 and r.close_price >= #{query.closePriceMin}
 and r.close_price <= #{query.closePriceMax}
 and r.ma120 >= #{query.ma120Min}
 and r.ma120 <= #{query.ma120Max}
 and r.price_ma120_ratio >= #{query.priceMa120RatioMin}
 and r.price_ma120_ratio <= #{query.priceMa120RatioMax}


        order by ${query.safeOrderBy}


        order by w.create_time desc, w.ts_code asc
